import { Analyzer, type Module, type Space, type Symbol } from 'yuku-analyzer';
import { anchorSymbol, resolveAnchor } from './anchors.ts';
import {
	makeReceipt,
	verifyReceipt,
	type Receipt,
	type SafeChangeIntent,
	type SafeChangeTarget,
	type SymbolAnchor,
} from './contracts.ts';
import {
	capturesOf,
	definitionOf,
	exportedNames,
	referencesOf,
	resolveBinding,
} from './queries.ts';
import { reachableFrom, reaches } from './reachability.ts';
import { safeChangeImpact } from './safe-change.ts';
import { safeChangeImpactSummary } from './progressive.ts';
import { analyzerSnapshot } from './snapshot.ts';

const supported = /\.(?:[cm]?[jt]s|jsx|tsx)$/;

export class GuesslessEngine {
	readonly analyzer = new Analyzer();

	addFile(path: string, source: string): Module | Receipt<never> {
		if (!supported.test(path))
			return makeReceipt({
				schema: 'guessless.receipt/v1',
				state: 'refused',
				query: 'addFile',
				request: { kind: 'addFile', file: path },
				snapshot: this.snapshot(),
				results: [],
				reason: 'unsupported-language',
				detail: `Unsupported language for '${path}'.`,
			});
		return this.analyzer.addFile(path, source);
	}
	removeFile(path: string): boolean {
		return this.analyzer.removeFile(path);
	}
	link(): void {
		this.analyzer.link();
	}
	module(path: string): Module | undefined {
		return this.analyzer.module(path);
	}
	snapshot(): string {
		return analyzerSnapshot(this.analyzer);
	}
	verify(receipt: unknown): receipt is Receipt<unknown> {
		return verifyReceipt(receipt, this.snapshot());
	}

	anchor(file: string, symbolName: string): SymbolAnchor | null {
		const module = this.analyzer.module(file);
		const matches = module?.symbols.filter((symbol) => symbol.name === symbolName) ?? [];
		return matches.length === 1 ? anchorSymbol(matches[0]) : null;
	}
	resolve(anchor: SymbolAnchor) {
		return resolveAnchor(this.analyzer.modules, anchor);
	}
	definitionOf(anchor: SymbolAnchor) {
		return definitionOf(this.analyzer, anchor);
	}
	referencesOf(anchor: SymbolAnchor) {
		return referencesOf(this.analyzer, anchor);
	}
	readsOf(anchor: SymbolAnchor) {
		return referencesOf(this.analyzer, anchor, 'reads');
	}
	writesOf(anchor: SymbolAnchor) {
		return referencesOf(this.analyzer, anchor, 'writes');
	}
	exportedNames(file: string) {
		const module = this.analyzer.module(file);
		return module === undefined
			? makeReceipt({
					schema: 'guessless.receipt/v1',
					state: 'refused',
					query: 'exportedNames',
					request: { kind: 'exportedNames', file },
					snapshot: this.snapshot(),
					results: [],
					reason: 'unresolved-symbol',
					detail: `Module '${file}' is not in the linked set.`,
				})
			: exportedNames(module);
	}
	capturesOf(anchor: SymbolAnchor) {
		return capturesOf(this.analyzer, anchor);
	}
	reachableFrom(anchor: SymbolAnchor) {
		return reachableFrom(this.analyzer, anchor);
	}
	reaches(anchor: SymbolAnchor) {
		return reaches(this.analyzer, anchor);
	}
	safeChangeImpact(snapshot: string, intent: SafeChangeIntent, target: SafeChangeTarget) {
		return safeChangeImpact(this.analyzer, snapshot, intent, target);
	}
	safeChangeImpactSummary(snapshot: string, intent: SafeChangeIntent, target: SafeChangeTarget) {
		return safeChangeImpactSummary(this.analyzer, snapshot, intent, target);
	}
	resolveBinding(file: string, name: string, space: Space = 'value', from?: SymbolAnchor) {
		const module = this.analyzer.module(file);
		if (module === undefined)
			return makeReceipt({
				schema: 'guessless.receipt/v1',
				state: 'refused',
				query: 'resolveBinding',
				request: { kind: 'resolveBinding', file, name, space, scope: from ?? null },
				snapshot: this.snapshot(),
				results: [],
				reason: 'unresolved-symbol',
				detail: `Module '${file}' is not in the linked set.`,
			});
		if (
			from !== undefined &&
			(from.file !== file || this.analyzer.module(from.file) !== module)
		)
			return makeReceipt({
				schema: 'guessless.receipt/v1',
				state: 'refused',
				query: 'resolveBinding',
				request: { kind: 'resolveBinding', file, name, space, scope: from },
				snapshot: this.snapshot(),
				results: [],
				reason: 'unresolved-symbol',
				detail: 'The scope anchor belongs to a different module; resolution fails closed.',
			});
		const resolvedFrom = from === undefined ? null : resolveAnchor(this.analyzer.modules, from);
		if (from !== undefined && resolvedFrom === null)
			return makeReceipt({
				schema: 'guessless.receipt/v1',
				state: 'refused',
				query: 'resolveBinding',
				request: { kind: 'resolveBinding', file, name, space, scope: from },
				snapshot: this.snapshot(),
				results: [],
				reason: 'unresolved-symbol',
				detail: 'The scope anchor is stale or ambiguous.',
			});
		const fromScope =
			resolvedFrom === null
				? undefined
				: 'flags' in resolvedFrom
					? (resolvedFrom as Symbol).scope
					: module.scopeOf(resolvedFrom);
		return resolveBinding(this.analyzer, module, name, space, fromScope, from ?? null);
	}
}
import { builtinModules } from 'node:module';
import type { Analyzer, Module } from 'yuku-analyzer';
import { anchorSite } from './anchors.ts';
import type { UnresolvedReason, UnresolvedSite } from './contracts.ts';

/**
 * Link honesty for supplied inputs.
 *
 * Yuku resolves relative specifiers against the supplied file set; every other
 * specifier is left unresolved. A build-tool alias ('containers/App/actions'
 * under webpack `resolve.modules`) is therefore indistinguishable from a real
 * package import by shape alone, and the importing file silently fails to join
 * the module graph: traversal queries neither answer from it nor name it.
 *
 * The only evidence available to the engine — without a second resolver, a
 * config reader, or the filesystem — is the supplied path set itself. So a
 * failed specifier that *names a supplied input* (matches some supplied path,
 * modulo extension, `/index`, and leading directories) is treated as a link
 * that should have been made and was not: reason 'unlinked-input'. A failed
 * specifier that names nothing in the supplied set is a recognized external or
 * builtin boundary and keeps its existing reason.
 *
 * The rule errs toward naming: a package specifier that happens to collide
 * with a supplied path is reported rather than assumed external.
 */

const nodeBuiltins = new Set([...builtinModules, ...builtinModules.map((name) => `node:${name}`)]);

const moduleExtensions = ['.tsx', '.ts', '.jsx', '.js', '.mts', '.mjs', '.cts', '.cjs'] as const;

function stripExtension(path: string): string {
	const extension = moduleExtensions.find((candidate) => path.endsWith(candidate));
	return extension === undefined ? path : path.slice(0, -extension.length);
}

function pathForms(path: string): string[] {
	const forms = new Set<string>([path]);
	const base = stripExtension(path);
	forms.add(base);
	if (base.endsWith('/index')) forms.add(base.slice(0, -'/index'.length));
	return [...forms].filter((form) => form.length > 0);
}

function segmentSuffixes(path: string): string[] {
	const parts = path.split('/');
	return parts
		.map((_, index) => parts.slice(index).join('/'))
		.filter((suffix) => suffix.length > 0);
}

const indexCache = new WeakMap<Analyzer, { key: string; keys: ReadonlySet<string> }>();

/**
 * Every name under which a supplied input could plausibly be requested: each
 * supplied path, without its extension, without a trailing '/index', and with
 * any number of leading directory segments dropped (alias roots are unknown).
 */
export function suppliedInputIndex(analyzer: Analyzer): ReadonlySet<string> {
	const key = [...analyzer.modules.keys()].sort().join('\u0000');
	const cached = indexCache.get(analyzer);
	if (cached !== undefined && cached.key === key) return cached.keys;
	const keys = new Set<string>();
	for (const path of analyzer.modules.keys())
		for (const form of pathForms(path))
			for (const suffix of segmentSuffixes(form)) keys.add(suffix);
	indexCache.set(analyzer, { key, keys });
	return keys;
}

function normalizeSpecifier(specifier: string): string {
	const withoutLoaders = specifier.slice(specifier.lastIndexOf('!') + 1);
	const withoutQuery = withoutLoaders.split('?')[0]?.split('#')[0] ?? '';
	return withoutQuery.replace(/\/+$/, '').replace(/^\/+/, '');
}

/**
 * True when an unresolved specifier could name a file that was supplied to the
 * engine. Relative specifiers are excluded: yuku resolves those against the
 * supplied set directly (exact, then extensions, then '/index'), so a relative
 * miss proves the target was never supplied.
 */
export function namesSuppliedInput(specifier: string, keys: ReadonlySet<string>): boolean {
	if (specifier.startsWith('.')) return false;
	const normalized = normalizeSpecifier(specifier);
	if (normalized.length === 0) return false;
	return pathForms(normalized).some((form) => keys.has(form));
}

export function boundaryReason(specifier: string, keys: ReadonlySet<string>): UnresolvedReason {
	if (nodeBuiltins.has(specifier)) return 'builtin-module-boundary';
	if (namesSuppliedInput(specifier, keys)) return 'unlinked-input';
	return specifier.startsWith('.') ? 'unresolved-specifier' : 'external-module-boundary';
}

export function boundaryDetail(
	kind: 'import' | 'export',
	specifier: string,
	reason: UnresolvedReason,
): string {
	const subject = kind === 'import' ? `Import '${specifier}'` : `Export from '${specifier}'`;
	return reason === 'unlinked-input'
		? `${subject} did not resolve, but names a supplied input; the link between these files could not be established.`
		: `${subject} leaves the linked file set.`;
}

/**
 * Names every supplied input outside the traversed graph whose own specifiers
 * failed to link to another supplied input. Such a file might belong in the
 * traversal and cannot be shown not to, so it is reported rather than dropped.
 * Modules already inside the traversed set are skipped: their boundaries are
 * named by the traversal's own gap collection, with identical anchors.
 */
export function unlinkedInputSites(
	analyzer: Analyzer,
	traversed: ReadonlySet<Module>,
	labelPrefix = '',
): UnresolvedSite[] {
	const keys = suppliedInputIndex(analyzer);
	const sites: UnresolvedSite[] = [];
	for (const module of analyzer.modules.values()) {
		if (traversed.has(module)) continue;
		for (const record of module.imports) {
			if (record.resolvedModule !== null) continue;
			if (boundaryReason(record.specifier, keys) !== 'unlinked-input') continue;
			sites.push({
				site: anchorSite(module, record.node, `${labelPrefix}import-boundary`),
				reason: 'unlinked-input',
				detail: boundaryDetail('import', record.specifier, 'unlinked-input'),
			});
		}
		for (const record of module.exports) {
			if (record.specifier === null || record.resolvedModule !== null) continue;
			if (boundaryReason(record.specifier, keys) !== 'unlinked-input') continue;
			sites.push({
				site: anchorSite(module, record.node, `${labelPrefix}export-boundary`),
				reason: 'unlinked-input',
				detail: boundaryDetail('export', record.specifier, 'unlinked-input'),
			});
		}
	}
	return sites;
}

