import { GuesslessEngine } from '../src/index.ts';

function run(label: string, files: Array<[string, string]>, query: string) {
	const engine = new GuesslessEngine();
	for (const [path, source] of files) engine.addFile(path, source);
	engine.link();
	const receipt = engine.exportedNames(query);
	console.log('===', label, receipt.state, 'integrity', receipt.integrity);
	console.log('  results', JSON.stringify(receipt.results.map((r) => r.name)));
	if ('unresolved' in receipt)
		for (const item of receipt.unresolved)
			console.log('   -', item.reason, '|', item.site.semanticPath.join('>'), '|', item.detail);
}

run(
	'q11 shape',
	[
		[
			'i18n.js',
			"const a = require('./a');\nfunction b() {}\nmodule.exports = { a, b };\nexports.c = 1;\n",
		],
	],
	'i18n.js',
);
run(
	'mixed',
	['mixed.js', 'export const a = 1;\nexport function b() {}\nmodule.exports.legacy = 2;\n'],
	['mixed.js'].length === 1 ? 'mixed.js' : 'mixed.js',
);
run(
	'adversarial',
	[
		[
			'weird.js',
			"const m = module;\nm.exports.x = 1;\nconst key = 'k';\nexports[key] = 2;\nconst e = module.exports;\ne.y = 3;\nif (module.hot) module.hot.accept();\nmodule[key] = 4;\nObject.assign(module.exports, { z: 5 });\n",
		],
	],
	'weird.js',
);
run('export equals', [['eq.ts', 'const foo = { a: 1 };\nexport = foo;\n']], 'eq.ts');
run(
	'pure es',
	[
		['pure.ts', 'export const a = 1;\nexport function b() {}\nexport default a;\n'],
		['barrel.ts', "export * from './pure.ts';\nexport const c = 2;\n"],
	],
	'pure.ts',
);
run(
	'barrel es',
	[
		['pure.ts', 'export const a = 1;\nexport function b() {}\nexport default a;\n'],
		['barrel.ts', "export * from './pure.ts';\nexport const c = 2;\n"],
	],
	'barrel.ts',
);
run(
	'barrel over cjs',
	[
		['cjs.js', 'module.exports = { a: 1 };\n'],
		['barrel2.js', "export * from './cjs.js';\nexport const c = 2;\n"],
	],
	'barrel2.js',
);
run(
	'es importing cjs stays complete',
	[
		['cjs.js', 'module.exports = { a: 1 };\n'],
		['app.js', "import cjs from './cjs.js';\nexport const c = cjs;\n"],
	],
	'app.js',
);

